'use strict';
const BASE='https://www.oltapazari.com.tr';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=s=>String(s).toLocaleLowerCase('tr-TR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i');
const money=n=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:n%1?2:0}).format(n);
const paths={search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',user:'M20 21v-2a6 6 0 0 0-6-6h-4a6 6 0 0 0-6 6v2M16 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0',bag:'M5 7h14l2 14H3L5 7ZM8 8V6a4 4 0 0 1 8 0v2',plus:'M12 5v14M5 12h14',minus:'M5 12h14',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',arrow:'M4 12h16m-6-6 6 6-6 6',upRight:'M7 17 17 7M7 7h10v10',close:'m6 6 12 12M6 18 18 6',home:'m3 10 9-7 9 7v11h-6v-7H9v7H3Z',check:'m5 12 4 4L19 6',shield:'m12 3 8 4v5c0 5-8 9-8 9s-8-4-8-9V7l8-4Zm-4 9 3 3 5-6',store:'M3 10h18L19 3H5L3 10Zm2 0v11h14V10M9 21v-7h6v7M3 10a3 3 0 0 0 6 0 3 3 0 0 0 6 0 3 3 0 0 0 6 0',sliders:'M4 7h16M4 17h16M8 4v6M16 14v6',fish:'M4 12c5-9 12-9 16 0-4 9-11 9-16 0ZM4 12 1 6v12l3-6Zm11-2h.01M10 6 8 3m2 15-2 3',compass:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Zm-6-3-2 4-4 2 2-4 4-2Z',book:'M12 5C8 2 3 3 3 3v16s5-1 9 2c4-3 9-2 9-2V3s-5-1-9 2Zm0 0v16',help:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Zm-12-3a3 3 0 1 1 5 2c-2 1-2 1-2 3m0 3h.01',wind:'M3 8h13a3 3 0 1 0-3-3M3 12h16a3 3 0 1 1-3 3M3 16h5a3 3 0 1 1-3 3',truck:'M1 5h13v12H1zM14 9h5l4 5v3h-9M8 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0Zm12 0a2 2 0 1 1-4 0 2 2 0 0 1 4 0',chat:'M21 11a9 9 0 0 1-9 9H3l1-5a9 9 0 1 1 17-4ZM8 11h.01M12 11h.01M16 11h.01',chevron:'m9 5 7 7-7 7',trash:'M3 6h18M5 6l1 15h12l1-15M9 6V3h6v3M10 10v7m4-7v7',compare:'M5 3v18M19 3v18M3 7h4m10 10h4M9 6h6M9 18h6',box:'m12 2 10 5v10l-10 5-10-5V7l10-5Zm0 10v10M2 7l10 5 10-5M7 4.5l10 5',phone:'M6 3 3 5c0 8 8 16 16 16l2-3-5-4-3 2c-3-1-4-2-5-5l2-3-4-5Z'};
Object.assign(paths,{menu:'M3 6h18M3 12h18M3 18h18',rod:'M4 21 18 3m-6 9 3 3m-5-1 3 3M18 3h3v12a4 4 0 0 1-8 0',waves:'M2 9c3-5 5 5 8 0s5 5 8 0 4 0 4 0M2 16c3-5 5 5 8 0s5 5 8 0 4 0 4 0',boat:'M3 13h18l-4 7H7l-4-7Zm9-10v10m0-10 7 7h-7M2 22c3-3 5 3 8 0s5 3 8 0 4 0 4 0',hook:'M12 2v12a5 5 0 1 1-10 0v-2l4 3m2-9h8',reel:'M17 11a6 6 0 1 1-12 0 6 6 0 0 1 12 0Zm-6 0h.01M11 5V2h5m1 9h4v7h-4M5 16l-3 6m9-5v5',line:'M3 6h18M3 18h18M6 6v12m12-12v12M6 9h12M6 12h12M6 15h12',pin:'M19 10c0 6-7 12-7 12S5 16 5 10a7 7 0 1 1 14 0Zm-4 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0',back:'M20 12H4m6-6-6 6 6 6',card:'M2 5h20v14H2zM2 10h20M6 15h3'});
function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.arrow}"/></svg>`}
function icons(root=document){$$('[data-icon]',root).forEach(x=>x.innerHTML=icon(x.dataset.icon))}
function load(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}
let DATA,products,toastTimer,state={favorites:load('op-favorites',[]),cart:load('op-cart',{}),compare:[],homeTab:'selected',demoOrder:null};
let checkoutDraft={name:'Deneme Kullanıcısı',phone:'0500 000 00 00',city:'İstanbul',district:'Kadıköy',address:'Örnek Mahallesi, Deneme Sokak No: 1',sameInvoice:true};
const techniques=[['LRF','Hafif takımla kıyı avı','fish'],['Spin','At–çek avcılığı','rod'],['Surf','Kıyıdan uzağa atış','waves'],['Jigging','Dikey avcılık','hook'],['Trolling','Tekne ilerlerken av','boat'],['Yemli','Doğal yemle av','hook'],['Sazan avı','Göl ve tatlı su','fish'],['Tekne avı','Tekneden avcılık','boat']];
const equipment=[['Olta Makineleri','Makine','reel'],['Olta Kamışları','Kamış','rod'],['Yapay Yemler','Yem','fish'],['İp ve Misina','İp & misina','line'],['Hazır Setler','Hazır set','box'],['Diğer Ekipmanlar','Diğer ekipmanlar','grid']];
function route(name,params={}){let q=new URLSearchParams(Object.entries(params).filter(([,v])=>v!==''&&v!=null)).toString();return '#'+name+(q?'?'+q:'')}
function external(url,label,cls=''){return `<a class="${cls}" href="${esc(url)}">${label}</a>`}
function current(){let raw=location.hash.slice(1)||'home',i=raw.indexOf('?');return {name:i<0?raw:raw.slice(0,i),params:new URLSearchParams(i<0?'':raw.slice(i+1))}}
function go(name,params={}){navigationByClick=true;scrollPositions.set(location.hash,window.scrollY);let h=route(name,params);if(location.hash===h)render(true,true);else location.hash=h}
function persist(){try{localStorage.setItem('op-favorites',JSON.stringify(state.favorites));localStorage.setItem('op-cart',JSON.stringify(state.cart))}catch{toast('Bu oturumda kullanabilirsin; tarayıcın seçimlerini kaydetmiyor.')}}
function toast(text,link=''){let t=$('#toast');t.innerHTML=esc(text)+(link?` <a href="${link}">Sepetimi aç →</a>`:'');t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),4500)}
function updateCounts(){$$('.cart-count').forEach(x=>x.textContent=Object.values(state.cart).reduce((a,b)=>a+b,0))}
function favorite(slug){let i=state.favorites.indexOf(slug);if(i>=0)state.favorites.splice(i,1);else state.favorites.push(slug);persist();$$('[data-favorite]').filter(x=>x.dataset.favorite===slug).forEach(b=>{let on=state.favorites.includes(slug);b.classList.toggle('selected',on);b.setAttribute('aria-pressed',on);b.setAttribute('aria-label',on?'Favorilerimden çıkar':'Favorilerime ekle');if(b.closest('.secondary-actions'))b.innerHTML=icon('heart')+(on?'Favorilerimden çıkar':'Favorilerime ekle')});toast(i>=0?'Favorilerinden çıkarıldı.':'Favorilerine eklendi.');if(current().params.has('favorites'))render(false)}
function addCart(slug,notify=true){let p=products.find(p=>p.slug===slug);if(!p||p.paymentMode!=='online'){toast('Bu ilanda alışveriş için satıcıyla görüşmelisin.');return false}if(p.stockStatus==='out'){toast('Bu ürün şu anda stokta yok.');return false}if((state.cart[slug]||0)>=(p.maxQty||99)){toast('Bu üründen en fazla '+(p.maxQty||99)+' adet seçebilirsin.');return false}state.cart[slug]=Math.min(p.maxQty||99,(state.cart[slug]||0)+1);persist();updateCounts();if(notify)toast('Ürün sepetine eklendi.','#cart');return true}
function modeLabel(p){return p.paymentMode==='online'?'Siteden satın al':p.paymentMode==='contact'?'Satıcıyla görüş':'Satış biçimini kontrol et'}
function pageShell(title,html,description=''){return `<div class="wrap page">${breadcrumb(title)}${heading(title,description)}${html}</div>`}
function sectionHead(title,desc,link,label='Tümünü gör'){return `<div class="section-head"><div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${link?`<a class="text-link" href="${link}">${label}${icon('arrow')}</a>`:''}</div>`}
function breadcrumb(label){return `<nav class="breadcrumb" aria-label="Sayfa yolu"><a href="#home">Ana sayfa</a>${icon('chevron')}<span>${esc(label)}</span></nav>`}
function heading(title,desc){return `<div class="page-heading"><h1>${esc(title)}</h1>${desc?`<p>${esc(desc)}</p>`:''}</div>`}
function empty(title,desc,action='Ürünleri keşfet',href='#catalog'){return `<div class="empty">${icon('search')}<h2>${esc(title)}</h2><p>${esc(desc)}</p><a class="button" href="${esc(href)}">${esc(action)}${icon('arrow')}</a></div>`}
function detailContent(p,tab){if(tab==='shipping')return `<h3>Teslimat ve iade bilgileri</h3><p>Kargo ücreti, hazırlık süresi ve iade koşulları ürüne ve satıcıya göre değişebilir. Satın almadan önce canlı sayfada belirtilen koşulları incele.</p><div class="help-contact">${external(BASE+'/'+p.slug,'Ürünün teslimat bilgileri '+icon('upRight'),'button small')}${external(BASE+'/iptal-ve-iade-politikasi','İptal ve iade politikası','button small outline')}</div>`;if(tab==='questions')return `<h3>Aklındaki soruyu satıcıya sor.</h3><p>Güncel yorumları okumak ve satıcıya soru göndermek için canlı ürün sayfasını kullanabilirsin.</p>${external(BASE+'/'+p.slug,'Soru ve yorumları aç '+icon('upRight'),'button small')}`;return `<h3>Ürün bilgileri</h3><div class="specs">${[['Marka',p.brand],['Kategori',p.category],['Satıcı',p.seller],['Satış türü',p.kind==='listing'?'Bireysel ilan':'Mağaza ürünü'],...(p.specs||[])].map(([k,v])=>`<div class="spec-row"><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('')}</div><p class="snapshot-note">Tam açıklama, fotoğraflar, teknik özellikler ve varsa renk/boy seçenekleri için ${external(BASE+'/'+p.slug,'canlı ürün sayfasını incele ↗')}.</p>`}
function storePage(){return `<div class="wrap">${breadcrumb('Mağazalar & markalar')}${heading('Balıkçılığın ortak adresleri.','Mağazaları tanı, ürünlerine göz at.')}<div class="store-grid">${DATA.stores.map(s=>external(s.url,`<span class="seller-avatar">${esc(s.name[0])}</span><div><h2>${esc(s.name)}</h2><p>Mağazayı ziyaret et</p></div>${icon('upRight')}`,'store-card')).join('')}</div>${sectionHead('Sevdiğin markaları bul','Aradığın markaya dokun, ürünlerine bak.')}<div class="services">${[...new Set(products.map(p=>p.brand))].filter(b=>b!=='Belirtilmemiş').sort((a,b)=>a.localeCompare(b,'tr')).map(b=>`<a class="service-link" href="${route('catalog',{brand:b})}">${esc(b)}${icon('arrow')}</a>`).join('')}</div>${external(BASE+'/markalar','Tüm markaları gör '+icon('upRight'),'button outline')}<div class="section"></div></div>`}
function sellPage(){return `<div class="wrap">${breadcrumb('Ürün sat')}${heading('Satmak mı istiyorsun? Buradan başla.','Sana uygun satış yolunu seç.')}<div class="cards-grid"><article class="info-card">${icon('user')}<div class="eyebrow">BİREYSEL SATICI</div><h2>Kendi ekipmanımı satacağım.</h2><p>Bir mağazan yoksa da ürününü ekleyebilirsin. Hesabına gir, ürün bilgilerini ve fotoğraflarını ekle.</p>${external(BASE+'/hesabim?ilan&pID=0','Ürünümü ekle '+icon('arrow'),'button')}</article><article class="info-card">${icon('store')}<div class="eyebrow">MAĞAZA SAHİBİ</div><h2>Mağazamı açacağım.</h2><p>İşletmenin ürünlerini balıkçılarla buluştur. Mağaza başvurusuyla satış sürecine başla.</p>${external(BASE+'/magaza/magaza-kayitol','Mağaza aç '+icon('arrow'),'button')}</article><article class="info-card">${icon('box')}<div class="eyebrow">MEVCUT SATICI</div><h2>Zaten mağazam var.</h2><p>Ürün, ilan, sipariş, kargo, ödeme ve hesap özeti işlemlerini satıcı panelinden yönet.</p>${external(BASE+'/magaza/magaza-giris','Satıcı paneline gir '+icon('arrow'),'button')}</article></div><section class="selling-banner"><span>${icon('help')}</span><div><h2>Nereden başlayacağını bilmiyor musun?</h2><p>Ekibimize yaz, sana yardımcı olalım.</p></div>${external('https://wa.me/+905405441515','WhatsApp’tan sor '+icon('chat'),'button')}</section></div>`}
function toolsPage(){const names=['Gemi Trafiği','Rüzgâr & Dalga','Deniz Tahmini','Deniz Sıcaklığı','Marina & Barınaklar','NAVTEX Uyarıları','Av Yasakları'];return `<div class="wrap">${breadcrumb('Balıkçı araçları')}${heading('Avdan önce bir kontrol et.','Hava, deniz, güvenlik ve kargo araçlarına tek yerden ulaş.')}<div class="cards-grid">${names.map((n,i)=>{let l=DATA.links.find(l=>l.title===n);return l?`<article class="info-card">${icon(i===1?'wind':'compass')}<h2>${n}</h2><p>İlgili kaynağın güncel bilgilerini incele.</p>${external(l.url,'Kaynağı aç '+icon('upRight'),'text-link')}</article>`:''}).join('')}</div><section class="tool-calculator"><h2>Kargo desisi hesapla</h2><p class="dialog-intro">Paketin ölçülerini santimetre olarak gir. Formül: en × boy × yükseklik ÷ 3000. Kargonun uyguladığı ücret değişebilir.</p><form id="desi-form"><div class="calculator-inputs">${['En','Boy','Yükseklik'].map((t,i)=>`<label class="field"><span>${t} (cm)</span><input type="number" name="d${i}" min="0.1" max="10000" step="any" required inputmode="decimal" placeholder="Örn. 30"></label>`).join('')}</div><button class="button small" type="submit">Hesapla ${icon('arrow')}</button></form><div id="desi-output" role="status"></div></section></div>`}
function directoryPage(){return `<div class="wrap">${breadcrumb('Tüm sayfalar & hizmetler')}${heading('Aradığın her şey burada.','Kategori, hesap, mağaza ve destek alanlarının tamamını burada bulabilirsin.')}<label class="field services-search"><span>Sayfa ya da kategori ara</span><input type="search" id="directory-search" placeholder="Örn. kamp, kupon, kargo, LRF…"></label><p class="directory-note" id="directory-count">${DATA.links.length} bağlantı</p><div class="services" id="directory-results">${directoryLinks(DATA.links)}</div></div>`}
function directoryLinks(links){if(!links.length)return empty('Bu isimde bir sayfa yok.','Farklı bir kelimeyle aramayı dene.','Tüm ürünlere bak','#catalog');let groups={'Kategoriler ve ekipmanlar':[],'Hesap ve satıcı işlemleri':[],'Mağazalar ve markalar':[],'Yardım ve kurumsal bilgiler':[],'Balıkçı araçları, uygulamalar ve topluluk':[],'Ürün sayfaları':[]};let slugs=new Set(products.map(p=>p.slug));const help=/destek|sikca|iletisim|hakkimizda|politika|sozlesme|metni|yasakli|sitemap|fatura-islemleri|kargo-olusturma|siparis-yonetimi|magaza-acma|desi-hesaplama/;for(let l of links){let u=new URL(l.url),path=u.pathname.slice(1);let g=slugs.has(path)?'Ürün sayfaları':/^(hesabim|magaza\/|giris|kayitol|cikis|satici-ol)/.test(path)?'Hesap ve satıcı işlemleri':help.test(path)?'Yardım ve kurumsal bilgiler':u.hostname!=='www.oltapazari.com.tr'||/blog|rehberi|teklif/.test(path)?'Balıkçı araçları, uygulamalar ve topluluk':/markalar|magazalar/.test(path)||DATA.stores.some(x=>x.url===l.url)?'Mağazalar ve markalar':'Kategoriler ve ekipmanlar';groups[g].push(l)}return Object.entries(groups).filter(([,ls])=>ls.length).map(([name,ls],i)=>`<details class="directory-group" ${i===0||links.length<DATA.links.length?'open':''}><summary>${name}<span>${ls.length} bağlantı</span></summary><div class="directory-group-links">${ls.map(l=>external(l.url,esc(l.title)+icon('upRight'),'service-link')).join('')}</div></details>`).join('')}
function productCard(p){let special=(p.kind==='listing'||p.paymentMode!=='online')&&p.stockStatus!=='out';return `<article class="product-card simple-product">${p.oldPrice&&p.oldPrice>p.price?`<span class="simple-discount">%${Math.round((1-p.price/p.oldPrice)*100)} indirim</span>`:''}<a class="product-image" href="${route('product',{id:p.slug})}"><img src="${p.image}" alt="${esc(p.name)}" width="300" height="300" loading="lazy"></a><div class="product-info"><h3 class="product-title"><a href="${route('product',{id:p.slug})}">${esc(p.name)}</a></h3><div class="price-row"><div>${p.oldPrice&&p.oldPrice>p.price?`<span class="old-price">${money(p.oldPrice)}</span>`:''}<span class="price">${money(p.price)}</span></div></div>${p.stockStatus==='out'?'<p class="stock-status out card-stock">Stokta yok</p>':''}${special?`<div class="payment-label ${p.paymentMode==='online'?'online':'contact'}">${modeLabel(p)}</div>`:''}<a class="button outline inspect-button" href="${route('product',{id:p.slug})}">İncele ${icon('arrow')}</a></div></article>`}
function disciplineTiles(){const names=['lrf','spin','surf','jigging','trolling','yemli','sazan','tekne'];return techniques.map(([t,d],i)=>`<a class="discipline-card photo-card" href="${route('discipline',{name:t})}"><div class="discipline-photo">${DATA.disciplineImages?.[names[i]]?`<img src="${DATA.disciplineImages[names[i]]}" alt="${esc(d)}" width="600" height="400" loading="${i<4?'eager':'lazy'}">`:''}</div><div class="discipline-card-copy"><h3>${t}</h3><p>${d}</p><span>${icon('arrow')}</span></div></a>`).join('')}
function homeFeatured(){let found=[];if(state.homeTab==='listing')return products.filter(p=>p.kind==='listing').slice(0,4);if(state.homeTab==='deals')return products.filter(p=>p.oldPrice).slice(0,4);for(let fn of [p=>p.slug==='shimano-stradic-sw-8000pg-olta-makinesi',p=>p.category==='Olta Kamışları'&&p.paymentMode==='online',p=>p.category==='Yapay Yemler'&&p.paymentMode==='online',p=>p.category==='Hazır Setler'&&p.paymentMode==='online']){let p=products.find(fn);if(p)found.push(p)}return found}
function home(){let deals=products.filter(p=>p.oldPrice&&p.oldPrice>p.price).slice(0,4);let chosen=['effe-alasca-lox-olta-seti-360-m-5000-makine','daiwa-24-airity-sf-1000s-p','prox-fish-catcher-r-regular-grip-balik-tutucu'];let picks=chosen.map(s=>products.find(p=>p.slug===s&&p.kind==='store')).filter(Boolean);let camera=products.find(p=>p.name.startsWith('CanFish')&&p.kind==='store');if(camera)picks.push(camera);let ranked=sortProducts(products.filter(p=>p.kind==='store'&&p.paymentMode==='online'&&p.stockStatus==='in'&&p.bestsellerRank),'bestselling');if(ranked.length>=4)picks=ranked.slice(0,4);if(picks.length<4)picks=[...new Map([...picks,...products.filter(p=>p.kind==='store'&&p.paymentMode==='online'&&!p.oldPrice)].map(p=>[p.slug,p])).values()].slice(0,4);return `<div class="wrap shop-home"><section class="section home-deals"><div class="section-head"><div><h1>Fırsat Avı</h1><p>İndirimli ürünlere göz at.</p></div><a class="text-link" href="#catalog?deal=1">Tüm indirimli ürünler ${icon('arrow')}</a></div><div class="product-grid deal-grid">${deals.map(productCard).join('')}</div></section><section class="section home-store">${sectionHead('Mağazalardan Seçili Ürünler','Çok satanlardan seçtiklerimiz.','#catalog?sort=bestselling','Tüm ürünler')}<div class="product-grid">${picks.map(productCard).join('')}</div></section><div class="home-assistance"><div><h2>Aradığını bulamadın mı?</h2><p>Tüm ürünlere bakabilir veya ekipman seçimi için yardım alabilirsin.</p></div><div><a class="button outline" href="#catalog">Tüm ürünleri gör ${icon('arrow')}</a><a class="text-link" href="#finder">Seçmeme yardım et ${icon('arrow')}</a></div></div></div>`}
function techniquesPage(){return pageShell('Nasıl avlanacaksın?',`<a class="simple-help" href="#finder">Kararsızım, yardımcı ol ${icon('arrow')}</a><div class="discipline-grid">${disciplineTiles()}</div><div class="section-end"><a class="text-link" href="#directory">Diğer tüm kategoriler ${icon('arrow')}</a></div>`,'Av türüne dokun. Sonraki ekranda ekipmanını seç.')}
function disciplinePage(params){let name=params.get('name')||'Spin',t=techniques.find(x=>x[0]===name);if(!t)return techniquesPage();let list=products.filter(p=>(p.disciplines||[]).includes(name)),categories=equipment.filter(([c])=>list.some(p=>p.category===c));return pageShell(name+' için ne arıyorsun?',`<a class="text-link change-discipline" href="#techniques">${icon('back')}Av türünü değiştir</a><div class="equipment-grid simple-equipment">${categories.map(([c,n])=>{let p=list.find(p=>p.category===c);return `<a class="equipment-card" href="${route('catalog',{discipline:name,category:c})}"><img src="${p.image}" alt="" width="220" height="150"><h2>${n}</h2>${icon('arrow')}</a>`}).join('')||`<div class="notice"><strong>Bu kategoride ${esc(name)} ürünü yok.</strong>Farklı bir kategori seçebilirsin.</div>`}</div><div class="section-end"><a class="button outline" href="${route('catalog',{discipline:name})}">Tüm ${esc(name)} ürünlerini gör ${icon('arrow')}</a></div><details class="source-categories"><summary>İlgili kategoriler</summary><div class="services">${(DATA.disciplineSources?.[name]||[]).map(([u,c])=>external(BASE+'/'+u,esc(c)+icon('upRight'),'service-link')).join('')}</div></details>`,'İhtiyacın olan ekipmana dokun.')}
function listingPage(){let online=products.filter(p=>p.kind==='listing'&&p.paymentMode==='online'),contact=products.filter(p=>p.kind==='listing'&&p.paymentMode==='contact');return pageShell('Bireysel ilanlar',`<div class="listing-choice-grid"><a class="listing-choice" href="#catalog?kind=listing&mode=online"><span>${icon('bag')}</span><h2>Siteden satın al</h2><p>Bu ürünlerde alışveriş ve ödeme site üzerinden yapılabilir.</p><strong>${online.length} ürün ${icon('arrow')}</strong></a><a class="listing-choice contact-choice" href="#catalog?kind=listing&mode=contact"><span>${icon('chat')}</span><h2>Satıcıyla görüş</h2><p>Bu ilanlarda online ödeme yok. Bilgi ve alışveriş için satıcıyla iletişime geç.</p><strong>${contact.length} ilan ${icon('arrow')}</strong></a></div><section class="section">${sectionHead('Balıkçılardan yeni bir hikâyeye','Her ilanda satış biçimi açıkça belirtilir.','#catalog?kind=listing','Tüm bireysel ilanlar')}<div class="product-grid">${[...online.slice(0,2),...contact.slice(0,2)].map(productCard).join('')}</div></section><div class="notice"><strong>Bireysel ilan her zaman ikinci el demek değildir.</strong>Ürünün durumunu açıklamasından kontrol et; gerektiğinde satıcıya sor.</div><div class="section-end"><a class="text-link" href="#sell">Sen de ürününü satmak mı istiyorsun? ${icon('arrow')}</a></div>`,'Mağaza olmadan satış yapan balıkçılara ulaş. İstersen online satın al, istersen satıcıyla görüş.')}
function productDetail(params){let p=products.find(p=>p.slug===params.get('id'));if(!p)return pageShell('Ürün bulunamadı',empty('Bu ürünü bulamadık.','Kataloğa dönüp başka bir ürüne bakabilirsin.'));let online=p.paymentMode==='online',saved=state.favorites.includes(p.slug);return `<div class="wrap page simple-detail">${breadcrumb(p.category)}<div class="product-detail"><div class="detail-image"><img src="${p.image}" alt="${esc(p.name)}" width="600" height="600"></div><section class="detail-info"><h1>${esc(p.name)}</h1><div class="detail-price">${p.oldPrice?`<span class="old-price">${money(p.oldPrice)}</span>`:''}<strong>${money(p.price)}</strong></div>${p.stockStatus==='out'?'<p class="stock-status out">Stokta yok</p>':p.stockStatus==='in'?'<p class="stock-status in">Stokta</p>':''}<p class="simple-seller">Satıcı: <a href="${route('catalog',{q:p.seller})}">${esc(p.seller)}</a></p>${p.kind==='listing'||!online?`<div class="simple-sale-mode"><strong>${p.stockStatus==='out'?'Stok bilgisi':modeLabel(p)}</strong>${!online?`<p>${p.stockStatus==='out'?'Ürünün yeniden ne zaman geleceğini satıcıya sorabilirsin.':'Bu ilanda satın almak için satıcıyla görüşmelisin.'}</p>`:''}</div>`:''}<div class="detail-buttons">${online?`${p.stockStatus==='out'?`<button class="button" disabled>Stokta yok</button><a class="text-link" href="${route('catalog',{category:p.category,stock:'1'})}">Stoktaki benzer ürünleri gör ${icon('arrow')}</a>`:`<button class="button" data-add="${esc(p.slug)}">Sepete ekle ${icon('arrow')}</button>`}`:external(route('contact',{id:p.slug}),(p.paymentMode==='contact'?'Satıcıyla iletişime geç':'Satıcıya sor')+' '+icon('upRight'),'button full')}</div><details class="secondary-actions"><summary>Kaydet ve karşılaştır</summary><button class="button outline" data-favorite="${esc(p.slug)}" aria-pressed="${saved}">${icon('heart')}${saved?'Favorilerimden çıkar':'Favorilerime ekle'}</button><label class="compare-check"><input type="checkbox" data-compare="${esc(p.slug)}" ${state.compare.includes(p.slug)?'checked':''}>Karşılaştırmaya ekle</label>${online&&p.stockStatus!=='out'?`<button class="text-link" data-buy="${esc(p.slug)}">Hemen al ${icon('arrow')}</button>`:''}</details></section></div><div class="detail-sections"><details open><summary>Ürün bilgileri</summary><div class="specs">${[['Marka',p.brand],['Kategori',p.category],['Satıcı',p.seller],['Alışveriş biçimi',modeLabel(p)],...(p.specs||[])].map(([k,v])=>`<div class="spec-row"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}</div>${(p.description||[]).map(x=>`<p>${esc(x)}</p>`).join('')}</details><details><summary>Teslimat ve iade bilgileri</summary><p>Teslimat süresi, kargo bedeli ve iade koşulları satıcıya ve ürüne göre değişebilir.</p>${external(BASE+'/iptal-ve-iade-politikasi','İade koşullarını oku ↗','text-link')}</details><details><summary>Satıcıya sor ve yorumları gör</summary><p>Ürünün durumunu veya merak ettiğin detayları satıcıya sor.</p><a class="button outline" href="${route('contact',{id:p.slug})}">Satıcıya soru sor ${icon('arrow')}</a></details></div></div>`}
function contactPage(params){let p=products.find(p=>p.slug===params.get('id'));if(!p)return helpPage();return pageShell('Satıcıya soru sor',`<form id="seller-question" class="contact-panel"><div class="mini-product"><img src="${p.image}" alt="${esc(p.name)}" width="110" height="110"><div><h2>${esc(p.name)}</h2><p>${esc(p.seller)}</p></div></div><label class="field"><span>Mesajın</span><textarea name="message" rows="5" required placeholder="Ürün hakkında ne öğrenmek istiyorsun?"></textarea></label><button class="button full" type="submit">Mesajı gönder ${icon('arrow')}</button><p class="form-note" id="question-result" role="status"></p></form>`)}

function guidePage(){return pageShell('Balıkçılık rehberi',`<a class="help-banner" href="#finder">${icon('compass')}<span><strong>İlk takımını birlikte bulalım.</strong><small>İki soru. Teknik bilgi gerektirmez.</small></span>${icon('arrow')}</a><div class="guide-grid">${DATA.links.filter(l=>l.title.length>45&&/rehberi|farklar|karşılaştır|tehlike/i.test(l.title)).filter((x,i,a)=>a.findIndex(y=>y.url===x.url)===i).slice(0,4).map((l,i)=>external(l.url,`<div class="article-visual">${icon(['book','reel','fish','compass'][i])}<span>Olta rehberi</span></div><div class="article-body"><h2>${esc(l.title)}</h2><strong>Yazıyı oku ${icon('arrow')}</strong></div>`,'article-card')).join('')}</div><div class="section-end">${external(BASE+'/blog','Tüm rehber yazılarını gör '+icon('upRight'),'button outline')}</div>`,'Teknik terimleri ve ekipman seçeneklerini sade anlatımlarla tanı.')}
function helpPage(){return pageShell('Nasıl yardımcı olabiliriz?',`<div class="help-contact">${external('https://wa.me/+905405441515',icon('chat')+'WhatsApp’tan yaz','button')}<a class="button outline" href="tel:+905405441515">${icon('phone')}Bizi ara</a><a class="button outline" href="mailto:info@oltapazari.com.tr">E-posta gönder</a></div><section class="faq">${[['Nasıl sipariş veririm?','Ürünü aç ve Sepete ekle’ye dokun. Sepetinde Teslimata devam et ile adresini seç. Son ekranda ürünlerini ve bilgilerini kontrol ederek siparişi tamamla.'],['Bireysel ilanlarda ödeme nasıl çalışıyor?','Siteden satın al etiketi olan ürünler sepete eklenebilir. Satıcıyla görüş etiketli ilanlarda online ödeme yoktur; satıcıya mesaj gönderebilirsin.'],['Ürün seçmekte zorlanıyorum.','Ana sayfadaki Nereden başlayacağımı bilmiyorum düğmesine dokun. Nerede balık tutacağını seçerek sana uygun başlangıç noktasını bulabilirsin.'],['Siparişlerimi nerede görebilirim?','Hesabım sayfasından Siparişlerim bölümüne ulaşabilirsin.'],['Favorilerime nasıl ürün eklerim?','Ürünün detayında Kaydet ve karşılaştır alanını aç. Favorilerime ekle’ye dokun. Favorilerine Hesabım’dan ulaşabilirsin.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section><div class="section-end"><a class="button outline" href="#directory">Tüm destek konuları ${icon('arrow')}</a></div>`,'Sorunun yanıtını bul ya da Olta Pazarı ekibine ulaş.')}

function accountPage(){let items=[['hesabim?aldiklarim','Sipariş ve iadeler','Siparişlerini takip et.','box'],['hesabim?favorilerim','Favorilerim','Beğendiğin ürünleri gör.','heart'],['hesabim?kuponlarim','Kuponlarım','Hesabına tanımlı kuponlar.','bag'],['hesabim?bilgilerim#userAddress','Adreslerim','Teslimat adreslerini düzenle.','pin'],['hesabim?bilgilerim','Hesap ayarlarım','Kişisel bilgilerini yönet.','sliders'],['hesabim?ilanlarim','Ürün ve ilanlarım','Bireysel satışlarını yönet.','grid']];return pageShell('Hesabım',`<section class="account-welcome"><span>${icon('user')}</span><div><h2>Hesabım</h2><p>Siparişlerini ve hesap bilgilerini buradan yönet.</p></div><div>${external(BASE+'/giris','Giriş yap','button')}${external(BASE+'/kayitol','Kayıt ol','button outline')}</div></section><div class="account-grid">${items.map(([u,n,d,i])=>external(u.includes('aldiklarim')?'#orders':u.includes('favorilerim')?'#catalog?favorites=1':BASE+'/'+u,icon(i)+`<span><strong>${n}</strong><small>${d}</small></span>`+icon('chevron'),'account-link')).join('')}</div><section class="section">${sectionHead('Seçimlerin','Beğendiğin ve seçtiğin ürünlere kolayca ulaş.')}<div class="quick-grid"><a class="quick-link" href="#cart">${icon('bag')}<strong>Sepetim</strong><span class="cart-count">0</span></a><a class="quick-link" href="#catalog?favorites=1">${icon('heart')}<strong>Favorilerim</strong><span>${state.favorites.length}</span></a><a class="quick-link" href="#compare">${icon('compare')}<strong>Karşılaştırma</strong><span>${state.compare.length}</span></a></div></section><section class="section">${sectionHead('Satış işlemleri','Bireysel ürün ekle veya mağazanı yönet.')}<div class="quick-grid"><a class="quick-link" href="#sell">${icon('plus')}<strong>Ürün sat / mağaza aç</strong>${icon('chevron')}</a>${external(BASE+'/magaza/magaza-giris',icon('store')+'<strong>Satıcı paneli</strong>'+icon('upRight'),'quick-link')}${external(BASE+'/hesabim?ilan&pID=0',icon('plus')+'<strong>Bireysel ilan ekle</strong>'+icon('upRight'),'quick-link')}</div></section>`)}
function menuPage(){let groups=[['Alışveriş',[['catalog','Tüm ürünler','grid'],['techniques','Av disiplinleri','compass'],['listings','Bireysel ilanlar','user'],['catalog?deal=1','İndirimli ürünler','bag'],['stores','Mağazalar ve markalar','store']]],['Hesabım',[['cart','Sepetim','bag'],['catalog?favorites=1','Favorilerim','heart'],['compare','Karşılaştırma','compare'],['account','Hesabım ve siparişlerim','user']]],['Yardım ve keşif',[['finder','Ekipman seçmeme yardım et','compass'],['guide','Balıkçılık rehberi','book'],['tools','Hava, deniz ve balıkçı araçları','wind'],['help','Yardım ve iletişim','help'],['directory','Tüm kategoriler ve hizmetler','grid']]],['Diğer',[['sell','Ürün sat / mağaza aç','store'],['settings','Dil ve para birimi','sliders'],['apps','Mobil uygulamalar','grid']]]];return pageShell('Nereye gitmek istersin?',`<div class="menu-grid">${groups.map(([t,ls])=>`<section class="menu-group"><h2>${t}</h2>${ls.map(([u,n,i])=>`<a href="#${u}">${icon(i)}<span>${n}</span>${icon('chevron')}</a>`).join('')}</section>`).join('')}</div>`,'Alışveriş, hesap ve destek alanlarına buradan ulaş.')}
function cartItems(){return Object.entries(state.cart).map(([s,q])=>({p:products.find(p=>p.slug===s),q})).filter(x=>x.p&&x.p.paymentMode==='online')}
function cartTotal(){return cartItems().reduce((s,{p,q})=>s+p.price*q,0)}
function orderSummary(button='',note=true){let list=cartItems();return `<aside class="order-summary"><h2>Sipariş özeti</h2><div class="summary-line"><span>${list.reduce((s,x)=>s+x.q,0)} ürün</span><strong>${money(cartTotal())}</strong></div><div class="summary-line"><span>Kargo ücreti</span><span>Teslimatta hesaplanır</span></div><div class="summary-total"><span>Ürün toplamı</span><strong>${money(cartTotal())}</strong></div>${button}${note?'<p class="summary-note">Devam etmeden önce ürünlerini ve teslimat bilgilerini kontrol et.</p>':''}<a class="summary-help" href="#help">${icon('help')}Yardıma ihtiyacım var</a></aside>`}
function cartPage(){let list=cartItems();if(!list.length)return pageShell('Sepetim',empty('Sepetin henüz boş.','Beğendiğin üründe Sepete ekle’ye dokun. Satıcıyla görüşülen ilanlar sepete eklenmez.'));return pageShell('Sepetim',`<div class="checkout-steps"><strong><span>1</span>Sepet</strong><span><i>2</i>Teslimat</span><span><i>3</i>Kontrol</span></div><div class="cart-layout"><section><div class="cart-products">${list.map(({p,q})=>`<article class="cart-item"><a href="${route('product',{id:p.slug})}"><img src="${p.image}" alt="${esc(p.name)}" width="110" height="110"></a><div class="cart-product-info"><p>${esc(p.seller)}</p><h2><a href="${route('product',{id:p.slug})}">${esc(p.name)}</a></h2><strong>${money(p.price)}</strong>${p.stockStatus==='out'?'<p class="stock-status out">Stokta yok</p>':''}<div class="quantity"><button data-qty="${esc(p.slug)}" data-delta="-1" ${q<=1?'disabled':''} aria-label="${esc(p.name)} adedini azalt">${icon('minus')}</button><span aria-live="polite">${q}</span><button data-qty="${esc(p.slug)}" data-delta="1" ${q>=(p.maxQty||99)?'disabled':''} aria-label="${esc(p.name)} adedini artır">${icon('plus')}</button></div></div><button class="remove-item" data-delete="${esc(p.slug)}" aria-label="${esc(p.name)} ürününü sepetten çıkar">${icon('trash')}<span>Çıkar</span></button></article>`).join('')}</div><a href="#catalog" class="text-link continue-shopping">${icon('back')}Alışverişe devam et</a></section>${orderSummary(list.some(x=>x.p.stockStatus==='out')?'<button class="button full" disabled>Stokta olmayan ürünü çıkar</button>':'<a class="button full" href="#checkout?step=address">Teslimata devam et '+icon('arrow')+'</a>')}</div>`,'Ürünlerini kontrol et, teslimata devam et.')}
function checkoutSteps(active){return `<nav class="checkout-steps" aria-label="Sipariş adımları"><a href="#cart"><span>1</span>Sepet</a><a href="#checkout?step=address" ${active==='address'?'aria-current="step"':''}><span>2</span>Teslimat</a><span class="${active==='review'?'active':''}"><i>3</i>Kontrol</span></nav>`}
function addressField(name,label,autocomplete,type='text'){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" autocomplete="${autocomplete}" value="${esc(checkoutDraft[name])}" aria-describedby="error-${name}" required><small id="error-${name}" class="field-error"></small></label>`}
function checkoutPage(params){if(cartItems().some(x=>x.p.stockStatus==='out'))return cartPage();if(!cartItems().length)return cartPage();let step=params.get('step')==='review'?'review':'address';if(step==='review')return pageShell('Son bir kontrol',`${checkoutSteps('review')}<div class="cart-layout"><section><div class="checkout-panel"><div class="panel-title"><h2>Teslimat adresi</h2><a href="#checkout?step=address">Değiştir</a></div><p><strong>${esc(checkoutDraft.name)}</strong><br>${esc(checkoutDraft.address)}<br>${esc(checkoutDraft.district)} / ${esc(checkoutDraft.city)}<br>${esc(checkoutDraft.phone)}</p></div>${!checkoutDraft.sameInvoice?`<div class="checkout-panel"><div class="panel-title"><h2>Fatura adresi</h2><a href="#checkout?step=address">Değiştir</a></div><p><strong>${esc(checkoutDraft.billingName)}</strong><br>${esc(checkoutDraft.billingAddress)}</p></div>`:''}<div class="checkout-panel"><h2>Ödeme yöntemi</h2><div class="demo-payment">${icon('card')}<div><strong>Kredi / banka kartı</strong></div>${icon('check')}</div></div><div class="checkout-panel"><h2>Ürünlerin</h2>${cartItems().map(({p,q})=>`<div class="review-product"><img src="${p.image}" alt="" width="64" height="64"><span><strong>${esc(p.name)}</strong><small>${q} adet</small></span><b>${money(p.price*q)}</b></div>`).join('')}</div></section>${orderSummary('<button class="button full" data-action="place-demo">Siparişi tamamla '+icon('arrow')+'</button>')}</div>`);return pageShell('Nereye teslim edilsin?',`${checkoutSteps('address')}<div class="cart-layout"><form id="address-form" class="checkout-panel" novalidate><div class="panel-title"><h2>Teslimat bilgileri</h2></div><div class="address-grid">${addressField('name','Ad soyad','name')}${addressField('phone','Telefon','tel','tel')}${addressField('city','İl','address-level1')}${addressField('district','İlçe','address-level2')}<label class="field address-full"><span>Açık adres</span><textarea name="address" rows="3" autocomplete="street-address" aria-describedby="error-address" required>${esc(checkoutDraft.address)}</textarea><small id="error-address" class="field-error"></small></label></div><label class="radio-field"><input type="checkbox" name="sameInvoice" ${checkoutDraft.sameInvoice?'checked':''}>Fatura adresim de aynı</label><div id="invoice-fields">${checkoutDraft.sameInvoice?'':billingFields()}</div><button class="button full" type="submit">Siparişi kontrol et ${icon('arrow')}</button></form>${orderSummary('',false)}</div>`)}
function orderPage(){let o=state.demoOrder;if(!o)return pageShell('Siparişlerim',empty('Henüz siparişin yok.','Ürünlere göz atarak alışverişe başlayabilirsin.'));return pageShell('Sipariş adımlarını tamamladın.',`<section class="order-success"><span class="success-check">${icon('check')}</span><h2>Teşekkürler.</h2><p>Bu denemede ödeme alınmadı ve gerçek sipariş oluşturulmadı.</p><div class="demo-number">${esc(o.id)}</div><div class="summary-line"><span>${o.qty} ürün</span><strong>${money(o.total)}</strong></div><div class="success-actions"><a class="button" href="#catalog">Alışverişe devam et ${icon('arrow')}</a><a class="button outline" href="#orders">Siparişlerim</a></div></section>`)}
function ordersPage(){let o=state.demoOrder;return pageShell('Siparişlerim',o?`<div class="checkout-panel"><h2>${esc(o.id)}</h2><p>${o.qty} ürün · ${money(o.total)}</p><p>Deneme akışı tamamlandı. Ödeme alınmadı.</p><a class="button outline" href="#order">Ayrıntıları gör ${icon('arrow')}</a></div>`:empty('Henüz siparişin yok.','Ürünlere göz atarak alışverişe başlayabilirsin.'))}

function comparePage(){let ps=state.compare.map(s=>products.find(p=>p.slug===s)).filter(Boolean);if(ps.length<2)return pageShell('Ürünleri karşılaştır',empty('En az iki ürün seç.','Ürün detayında Kaydet ve karşılaştır alanını aç. En az iki, en fazla üç ürün seçebilirsin.'));return pageShell('Ürünleri karşılaştır',`<div class="compare-scroll"><table class="compare-table"><thead><tr><th>Ürün</th>${ps.map(p=>`<th><a href="${route('product',{id:p.slug})}"><img src="${p.image}" alt="${esc(p.name)}" width="180" height="160">${esc(p.name)}</a></th>`).join('')}</tr></thead><tbody>${[['Fiyat',p=>money(p.price)],['Kategori',p=>p.category],['Marka',p=>p.brand],['Satıcı',p=>p.seller],['Alışveriş biçimi',p=>modeLabel(p)],['Stok',p=>p.stockStatus==='in'?'Stokta':p.stockStatus==='out'?'Stokta yok':'Belirtilmemiş']].map(([k,fn])=>`<tr><th scope="row">${k}</th>${ps.map(p=>`<td>${esc(fn(p))}</td>`).join('')}</tr>`).join('')}<tr><th>İncele</th>${ps.map(p=>`<td><a class="button small" href="${route('product',{id:p.slug})}">Ürüne bak</a><button class="text-link" data-uncompare="${esc(p.slug)}">Çıkar</button></td>`).join('')}</tr></tbody></table></div><p class="snapshot-note">Teknik özellikleri ve ürün durumunu satın almadan önce kontrol et.</p>`,'Seçeneklerini yan yana gör. Karar verirken hatırlamak zorunda kalma.')}
function finderPage(params){let place=params.get('place'),level=params.get('level');if(!place)return pageShell('Birlikte bulalım.',`<div class="finder-card"><div class="step-kicker">1 / 2 · Av yerin</div><h2>Nerede balık tutacaksın?</h2><p>En yakın seçeneği işaretle.</p><div class="finder-options">${[['shore','Kıyıdan','Sahil, iskele veya kayalık','waves'],['boat','Tekneden','Tekneyle denizde','boat'],['fresh','Göl veya akarsuda','Tatlı suda','fish'],['unsure','Henüz bilmiyorum','Yeni başlıyorum','compass']].map(([v,n,d,i])=>`<a href="${route('finder',{place:v})}">${icon(i)}<span><strong>${n}</strong><small>${d}</small></span>${icon('chevron')}</a>`).join('')}</div></div>`,'Teknik bilgi gerektirmeyen iki basit soru.');if(!level)return pageShell('Nasıl başlamak istersin?',`<a class="text-link" href="#finder">${icon('back')}Av yerini değiştir</a><div class="finder-card"><div class="step-kicker">2 / 2 · Deneyimin</div><h2>Sana en uygun seçenek hangisi?</h2><div class="finder-options">${[['beginner','Yeni başlıyorum','Hazır setlerle kolayca başlayayım.','box'],['experienced','Takımımı geliştireceğim','İhtiyacım olan parçayı seçeyim.','reel']].map(([v,n,d,i])=>`<a href="${route('finder',{place,level:v})}">${icon(i)}<span><strong>${n}</strong><small>${d}</small></span>${icon('chevron')}</a>`).join('')}</div></div>`);let beginner=level==='beginner',dis=place==='boat'?'Tekne avı':place==='fresh'?'Sazan avı':'Spin',u=beginner?route('catalog',{category:'Hazır Setler'}):route('discipline',{name:dis});return pageShell('Başlangıç noktan hazır.',`<div class="finder-result"><span class="success-check">${icon('compass')}</span><h2>${beginner?'Hazır olta setlerine bakabilirsin.':dis+' ekipmanlarından başlayabilirsin.'}</h2><p>Bu öneri seni doğru kategoriye yönlendirir. Son seçimi yapmadan önce hedef balığı, av yerini ve bütçeni satıcıyla değerlendirebilirsin.</p><a class="button" href="${u}">Ürünleri keşfet ${icon('arrow')}</a><a class="button outline" href="#finder">Baştan seç</a></div>`)}
function settingsPage(){return pageShell('Dil ve para birimi',`<div class="settings-card"><h2>Dil seçenekleri</h2><p>Türkçe, Arapça, İspanyolca, İngilizce, Almanca, Fransızca, Japonca ve Rusça.</p><p>TL, USD, EUR, GBP ve CNY para birimleri seçenekleri kullanılabilir.</p>${external(BASE+'/','Tercihleri değiştir '+icon('upRight'),'button')}</div>`,'Dil ve para birimi tercihlerini yönet.')}
function appsPage(){let ls=DATA.links.filter(l=>/apps.apple.com|play.google.com/.test(l.url));return pageShell('Olta Pazarı cebinde.',`<div class="settings-card"><h2>Resmi uygulamayı indir.</h2><div class="help-contact">${ls.slice(0,2).map(l=>external(l.url,l.url.includes('apple')?'App Store ↗':'Google Play ↗','button')).join('')}</div></div>`)}
function footer(){return `<div class="wrap simple-footer"><a class="brand" href="#home"><img src="${DATA.logo}" alt="Olta Pazarı" width="190" height="34"></a><nav aria-label="Alt menü"><a href="#help">Yardım</a><a href="#directory">Tüm hizmetler</a><a href="#sell">Satıcı işlemleri</a>${external(BASE+'/gizlilik-politikasi','Gizlilik')}</nav><p>© 2026 Olta Pazarı</p></div>`}
let scrollPositions=new Map(),navigationByClick=false;
function updateCompareTray(){let prev=$('#compare-tray');if(prev)prev.remove();let name=current().name;if(!state.compare.length||['compare','cart','checkout','order'].includes(name))return;let el=document.createElement('div');el.id='compare-tray';el.className='compare-tray';el.innerHTML=`<span>${state.compare.length} ürün seçtin</span><a class="button small" href="#compare">Karşılaştır ${icon('arrow')}</a><button data-action="clear-compare" aria-label="Seçimi temizle">${icon('close')}</button>`;document.body.append(el)}
function compare(slug,on){if(on&&state.compare.length>=3&&!state.compare.includes(slug)){toast('En fazla 3 ürünü yan yana karşılaştırabilirsin.');$$('[data-compare]').filter(x=>x.dataset.compare===slug).forEach(x=>x.checked=false);return}if(on&&!state.compare.includes(slug))state.compare.push(slug);if(!on)state.compare=state.compare.filter(s=>s!==slug);$$('[data-compare]').filter(x=>x.dataset.compare===slug).forEach(x=>x.checked=on);try{localStorage.setItem('op-compare',JSON.stringify(state.compare))}catch{}updateCompareTray()}
function render(restore=true,forceTop=false){if(!DATA)return;let {name,params}=current();document.body.classList.toggle('checkout-mode',['checkout','order'].includes(name));const pages={home,catalog:()=>catalog(params),techniques:techniquesPage,discipline:()=>disciplinePage(params),product:()=>productDetail(params),listings:listingPage,stores:storePage,sell:sellPage,tools:toolsPage,directory:directoryPage,guide:guidePage,help:helpPage,account:accountPage,menu:menuPage,cart:cartPage,checkout:()=>checkoutPage(params),order:orderPage,orders:ordersPage,filters:()=>filtersPage(params),compare:comparePage,finder:()=>finderPage(params),settings:settingsPage,apps:appsPage,contact:()=>contactPage(params)};$('#main').innerHTML=(pages[name]||(()=>pageShell('Sayfa bulunamadı',empty('Bu sayfayı bulamadık.','Ana sayfadan tekrar başlayabilirsin.','Ana sayfaya dön','#home'))))();document.title=name==='home'?'Olta Pazarı | Balıkçılık ekipmanları':($('#main h1')?.textContent||'Olta Pazarı')+' | Olta Pazarı';$('#search-input').value=name==='catalog'?(params.get('q')||''):'';$$('[data-nav]').forEach(a=>{let active=(a.dataset.nav===name&&!(name==='catalog'&&(params.has('deal')||params.has('favorites')||params.get('kind')==='listing')))||(a.dataset.nav==='deals'&&params.has('deal'))||(a.dataset.nav==='techniques'&&name==='discipline')||(a.dataset.nav==='listings'&&params.get('kind')==='listing');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$$('[data-mobile]').forEach(a=>a.classList.toggle('active',a.dataset.mobile===name||(a.dataset.mobile==='favorites'&&params.has('favorites'))||(a.dataset.mobile==='techniques'&&['discipline','catalog','listings'].includes(name)&&!params.has('favorites'))));updateCounts();updateCompareTray();if(name==='filters')updateFilterPreview();if(restore){let y=forceTop?0:(scrollPositions.get(location.hash)||0);$('#main').focus({preventScroll:true});requestAnimationFrame(()=>window.scrollTo({top:y,behavior:'instant'}))}}
function placeDemo(){if(cartItems().some(x=>x.p.stockStatus==='out')){toast('Stokta olmayan ürünü sepetinden çıkar.');go('cart');return}if(!cartItems().length){go('cart');return}state.demoOrder={id:'DENEME-'+Date.now().toString().slice(-7),qty:cartItems().reduce((s,x)=>s+x.q,0),total:cartTotal()};go('order')}
function saveAddress(form){let fd=Object.fromEntries(new FormData(form)),errors={};if((fd.name||'').trim().length<2)errors.name='Adını ve soyadını yaz.';if((fd.phone||'').replace(/\D/g,'').length<10)errors.phone='En az 10 haneli bir telefon numarası yaz.';if(!(fd.city||'').trim())errors.city='İl bilgisini yaz.';if(!(fd.district||'').trim())errors.district='İlçe bilgisini yaz.';if((fd.address||'').trim().length<10)errors.address='Adresini biraz daha ayrıntılı yaz.';for(let k of ['name','phone','city','district','address']){let input=form.elements[k],err=$('#error-'+k,form);err.textContent=errors[k]||'';input.setAttribute('aria-invalid',errors[k]?'true':'false')}if(!fd.sameInvoice){if(!(fd.billingName||'').trim())errors.billingName='Fatura adı veya ünvanını yaz.';if((fd.billingAddress||'').trim().length<10)errors.billingAddress='Fatura adresini yaz.';for(let k of ['billingName','billingAddress']){form.elements[k].setAttribute('aria-invalid',errors[k]?'true':'false');$('#error-'+k,form).textContent=errors[k]||''}}let first=Object.keys(errors)[0];if(first){form.elements[first].focus();return false}checkoutDraft={...checkoutDraft,...fd,sameInvoice:!!fd.sameInvoice};return true}
const actions={account:()=>go('account'),categories:()=>go('techniques'),cart:()=>go('cart'),favorites:()=>go('catalog',{favorites:'1'}),filters:()=>go('filters',Object.fromEntries(current().params)),wizard:()=>go('finder'),comparison:()=>go('compare'),'clear-compare':()=>{state.compare=[];$$('[data-compare]').forEach(x=>x.checked=false);try{localStorage.setItem('op-compare','[]')}catch{}updateCompareTray()},'place-demo':placeDemo,preferences:()=>go('settings'),apps:()=>go('apps')};
document.addEventListener('click',e=>{let a=e.target.closest('a[href^="#"]');if(a){scrollPositions.set(location.hash,window.scrollY);navigationByClick=true;if(a.getAttribute('href')===location.hash&&!a.classList.contains('skip')){e.preventDefault();window.scrollTo({top:0,behavior:'instant'});navigationByClick=false;return}}if(a?.classList.contains('skip')){e.preventDefault();$('#main').focus();$('#main').scrollIntoView();return}let el=e.target.closest('[data-action],[data-favorite],[data-add],[data-buy],[data-home-tab],[data-remove-filter],[data-qty],[data-delete],[data-uncompare],[data-price-min]');if(!el)return;if(el.hasAttribute('data-price-min')){let form=el.closest('form');form.elements.min.value=el.dataset.priceMin;form.elements.max.value=el.dataset.priceMax;updateFilterPreview();return}if(el.dataset.action){actions[el.dataset.action]?.();return}if(el.dataset.favorite){favorite(el.dataset.favorite);return}if(el.dataset.add){let p=products.find(p=>p.slug===el.dataset.add);if(p&&p.paymentMode==='online'&&p.stockStatus!=='out'&&(state.cart[p.slug]||0)>=(p.maxQty||99)){go('cart');toast('Bu ürün zaten sepetinde.');return}if(addCart(el.dataset.add,false))go('cart');return}if(el.dataset.buy){let p=products.find(p=>p.slug===el.dataset.buy);if(p&&p.paymentMode==='online'&&p.stockStatus!=='out'&&state.cart[p.slug]){go('checkout',{step:'address'});return}if(addCart(el.dataset.buy,false))go('checkout',{step:'address'});return}if(el.dataset.homeTab){state.homeTab=el.dataset.homeTab;$$('[data-home-tab]').forEach(x=>{x.classList.toggle('active',x===el);x.setAttribute('aria-pressed',x===el)});$('#home-products').innerHTML=homeFeatured().map(productCard).join('');return}if(el.dataset.removeFilter){let {params}=current(),key=el.dataset.removeFilter;if(key==='brand'&&el.dataset.filterValue){let brands=values(params,'brand').filter(v=>normalize(v)!==normalize(el.dataset.filterValue));if(brands.length)params.set('brand',brands.join(','));else params.delete('brand')}else params.delete(key);params.delete('page');go('catalog',Object.fromEntries(params));return}if(el.dataset.qty){let s=el.dataset.qty;let p=products.find(p=>p.slug===s);state.cart[s]=Math.max(1,Math.min(p?.maxQty||99,(state.cart[s]||0)+Number(el.dataset.delta)));persist();render(false);return}if(el.dataset.delete){delete state.cart[el.dataset.delete];persist();render(false);toast('Ürün sepetinden çıkarıldı.');return}if(el.dataset.uncompare){compare(el.dataset.uncompare,false);render(false)}});
document.addEventListener('change',e=>{if(e.target.closest('.refined-filters'))updateFilterPreview();if(e.target.matches('[data-compare]'))compare(e.target.dataset.compare,e.target.checked);if(e.target.id==='sort'){let {params}=current();params.set('sort',e.target.value);params.delete('page');go('catalog',Object.fromEntries(params))}if(e.target.name==='sameInvoice')$('#invoice-fields').innerHTML=e.target.checked?'':billingFields()});
document.addEventListener('input',e=>{if(e.target.id==='brand-search'){let term=normalize(e.target.value),shown=0;$$('[data-brand-label]').forEach(l=>{let show=l.dataset.brandLabel.includes(term);l.hidden=!show;if(show)shown++});$('#brand-empty').hidden=shown>0;return}if(e.target.closest('.refined-filters'))updateFilterPreview();if(e.target.id==='directory-search'){let term=normalize(e.target.value),ls=DATA.links.filter(l=>normalize(l.title).includes(term));$('#directory-results').innerHTML=directoryLinks(ls);$('#directory-count').textContent=ls.length+' bağlantı'}});
document.addEventListener('submit',e=>{if(e.target.id==='search'){e.preventDefault();go('catalog',{q:$('#search-input').value.trim()});return}if(e.target.matches('.filter-form')){e.preventDefault();let fd=readFilterForm(e.target);if(fd.min&&fd.max&&Number(fd.min)>Number(fd.max)){toast('En az fiyat, en fazla fiyattan büyük olamaz.');return}go('catalog',fd);return}if(e.target.id==='seller-question'){e.preventDefault();$('#question-result').textContent='Mesaj alanı denendi. Bu oturumda satıcıya mesaj gönderilmedi.';return}if(e.target.id==='address-form'){e.preventDefault();if(saveAddress(e.target))go('checkout',{step:'review'});return}if(e.target.id==='desi-form'){e.preventDefault();let fd=new FormData(e.target),v=Number(fd.get('d0'))*Number(fd.get('d1'))*Number(fd.get('d2'))/3000;$('#desi-output').innerHTML=`<div class="desi-result"><strong>${new Intl.NumberFormat('tr-TR',{maximumFractionDigits:2}).format(v)}</strong> desi<p>Kargo firması desiyi yuvarlayabilir ve gerçek ağırlıkla karşılaştırabilir.</p></div>`}});
window.addEventListener('hashchange',()=>{render(true,navigationByClick);navigationByClick=false});
icons();fetch('data.json').then(r=>{if(!r.ok)throw Error('catalog');return r.json()}).then(d=>{DATA=d;products=d.products;state.favorites=Array.isArray(state.favorites)?state.favorites.filter(s=>products.some(p=>p.slug===s)):[];state.cart=state.cart&&typeof state.cart==='object'&&!Array.isArray(state.cart)?Object.fromEntries(Object.entries(state.cart).filter(([s,n])=>products.some(p=>p.slug===s&&p.paymentMode==='online')&&Number.isInteger(n)&&n>0&&n<=99).map(([s,n])=>[s,Math.min(n,products.find(p=>p.slug===s).maxQty||99)])):{};state.compare=load('op-compare',[]);if(!Array.isArray(state.compare))state.compare=[];state.compare=state.compare.filter(s=>products.some(p=>p.slug===s)).slice(0,3);$('#footer').innerHTML=footer();render(false)}).catch(()=>{$('#main').innerHTML=pageShell('İçerik yüklenemedi.',empty('Bir bağlantı sorunu var.','Sayfayı yenileyip tekrar deneyebilirsin.','Tekrar dene','#home'))});

function liveCategoryUrl(discipline,category=''){let ls=DATA.disciplineSources?.[discipline]||[];let x=ls.find(([,c])=>c===category)||ls[0];return x?BASE+'/'+x[0]:BASE+'/balikcilik'}

function billingFields(){return `<div class="billing-fields"><h3>Fatura bilgileri</h3>${addressField('billingName','Ad soyad / ünvan','organization')}<label class="field"><span>Fatura adresi</span><textarea name="billingAddress" rows="3" aria-describedby="error-billingAddress">${esc(checkoutDraft.billingAddress||'')}</textarea><small id="error-billingAddress" class="field-error"></small></label></div>`}
function values(params,key){return (params.get(key)||'').split(',').map(x=>x.trim()).filter(Boolean)}
function filterProducts(params){const brands=values(params,'brand').map(normalize),q=normalize(params.get('q')||'').split(/\s+/).filter(Boolean);return products.filter(p=>q.every(t=>normalize(p.name+' '+p.brand+' '+p.seller+' '+p.category).includes(t))&&(!params.get('discipline')||(p.disciplines||[]).includes(params.get('discipline')))&&(!params.get('category')||p.category===params.get('category'))&&(!brands.length||brands.includes(normalize(p.brand)))&&(!params.get('kind')||p.kind===params.get('kind'))&&(!params.get('mode')||p.paymentMode===params.get('mode'))&&(!params.get('min')||p.price>=Number(params.get('min')))&&(!params.get('max')||p.price<=Number(params.get('max')))&&(!params.has('deal')||(p.oldPrice&&p.oldPrice>p.price))&&(!params.has('favorites')||state.favorites.includes(p.slug))&&(!params.has('stock')||p.stockStatus==='in')&&(!params.get('condition')||p.condition===params.get('condition'))&&(!params.get('dateStart')||(p.publishedDate&&p.publishedDate>=params.get('dateStart')))&&(!params.get('dateEnd')||(p.publishedDate&&p.publishedDate<=params.get('dateEnd'))))}
function sortProducts(list,sort){const rank=(p,k)=>p[k]||Number.MAX_SAFE_INTEGER;const discount=p=>p.oldPrice>p.price?(p.oldPrice-p.price)/p.oldPrice:0;return [...list].sort((a,b)=>{let v=0;if(sort==='recommended')v=Number(a.stockStatus==='out')-Number(b.stockStatus==='out')||Number(a.paymentMode!=='online')-Number(b.paymentMode!=='online')||rank(a,'bestsellerRank')-rank(b,'bestsellerRank');else if(sort==='price-asc')v=a.price-b.price;else if(sort==='price-desc')v=b.price-a.price;else if(sort==='bestselling')v=rank(a,'bestsellerRank')-rank(b,'bestsellerRank');else if(sort==='most-viewed')v=rank(a,'viewRank')-rank(b,'viewRank');else if(sort==='newest')v=rank(a,'newRank')-rank(b,'newRank')||(b.publishedDate||'').localeCompare(a.publishedDate||'');else if(sort==='discount-desc')v=discount(b)-discount(a);else if(sort==='name')v=a.name.localeCompare(b.name,'tr');return v})}
function readFilterForm(form){const fd=new FormData(form),out={};for(const key of ['q','discipline','category','kind','mode','min','max','condition','dateStart','dateEnd','sort','deal','stock','favorites']){let v=fd.get(key);if(v)out[key]=String(v).trim()}let brands=fd.getAll('brand').map(String);if(brands.length)out.brand=brands.join(',');return out}
function filterForm(params){const chosen=values(params,'brand').map(normalize),allBrands=[...new Set(products.map(p=>p.brand))].filter(b=>b!=='Belirtilmemiş').sort((a,b)=>a.localeCompare(b,'tr')),allCats=[...new Set(products.map(p=>p.category))].sort((a,b)=>a.localeCompare(b,'tr'));const conditionNames=[['new','Sıfır'],['used','İkinci el'],['refurbished','Yenilenmiş'],['unknown','Durumu belirtilmemiş']];return `<form class="filter-form refined-filters"><div class="filter-reset-row"><span>Seçimlerini yap, ardından ürünleri göster.</span><a class="text-link" href="${route('filters',{q:params.get('q')||'',favorites:params.has('favorites')?'1':''})}">Tümünü temizle</a></div><section class="filter-section"><h2>Ne arıyorsun?</h2><label class="field"><span>Ürün, marka veya satıcı</span><input name="q" type="search" value="${esc(params.get('q')||'')}" placeholder="Örn. Shimano spin"></label><div class="filter-two"><label class="field"><span>Av türü</span><select name="discipline"><option value="">Tüm av türleri</option>${techniques.map(([t])=>`<option ${params.get('discipline')===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field"><span>Ekipman</span><select name="category"><option value="">Tüm ekipmanlar</option>${allCats.map(c=>`<option ${params.get('category')===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label></div></section><section class="filter-section"><h2>Fiyat aralığı</h2><div class="price-inputs"><label class="field"><span>En az (TL)</span><input type="number" name="min" min="0" step="any" inputmode="decimal" placeholder="0" value="${esc(params.get('min')||'')}"></label><label class="field"><span>En fazla (TL)</span><input type="number" name="max" min="0" step="any" inputmode="decimal" placeholder="Sınır yok" value="${esc(params.get('max')||'')}"></label></div><div class="price-presets"><button type="button" data-price-min="" data-price-max="500">500 TL’ye kadar</button><button type="button" data-price-min="500" data-price-max="2000">500–2.000 TL</button><button type="button" data-price-min="2000" data-price-max="">2.000 TL ve üzeri</button></div><p class="field-error" id="price-error" role="alert"></p><label class="radio-field"><input type="checkbox" name="deal" value="1" ${params.has('deal')?'checked':''}>Sadece indirimli ürünler</label><label class="radio-field"><input type="checkbox" name="stock" value="1" ${params.has('stock')?'checked':''}>Sadece stoktakiler</label></section><details class="filter-accordion" ${chosen.length?'open':''}><summary>Marka <span id="brand-selection-summary">${chosen.length?chosen.length+' marka seçili':'Birden fazla seçebilirsin'}</span></summary><label class="field brand-search"><span>Marka ara</span><input type="search" id="brand-search" placeholder="Marka adını yaz"></label><div class="brand-options">${allBrands.map(b=>`<label class="radio-field brand-option" data-brand-label="${esc(normalize(b))}"><input type="checkbox" name="brand" value="${esc(b)}" ${chosen.includes(normalize(b))?'checked':''}><span>${esc(b)}</span><small data-brand-count="${esc(b)}"></small></label>`).join('')}</div><p id="brand-empty" hidden>Bu isimde marka bulunamadı.</p></details><details class="filter-accordion" ${params.get('kind')||params.get('mode')?'open':''}><summary>Satıcı ve ödeme <span>Mağaza, bireysel, online veya iletişim</span></summary><div class="filter-two"><div><h3>Kimden almak istersin?</h3>${[['','Hepsi'],['store','Mağazadan'],['listing','Bireysel satıcıdan']].map(([v,t])=>`<label class="radio-field"><input type="radio" name="kind" value="${v}" ${v===(params.get('kind')||'')?'checked':''}>${t}</label>`).join('')}</div><div><h3>Nasıl alışveriş yapacaksın?</h3>${[['','Hepsi'],['online','Siteden satın al'],['contact','Satıcıyla görüş']].map(([v,t])=>`<label class="radio-field"><input type="radio" name="mode" value="${v}" ${v===(params.get('mode')||'')?'checked':''}>${t}</label>`).join('')}</div></div></details><details class="filter-accordion" ${params.get('condition')||params.get('dateStart')||params.get('dateEnd')?'open':''}><summary>Diğer seçenekler <span>Ürün durumu ve ilan tarihi</span></summary><label class="field"><span>Ürün durumu</span><select name="condition"><option value="">Tümü</option>${conditionNames.map(([v,t])=>{let count=products.filter(p=>p.condition===v).length;return `<option value="${v}" ${params.get('condition')===v?'selected':''} ${count===0?'disabled':''}>${t} (${count})</option>`}).join('')}</select></label><div class="filter-two"><label class="field"><span>İlan tarihi: başlangıç</span><input type="date" name="dateStart" value="${esc(params.get('dateStart')||'')}"></label><label class="field"><span>İlan tarihi: bitiş</span><input type="date" name="dateEnd" value="${esc(params.get('dateEnd')||'')}"></label></div><p class="form-note">Tarih seçimi, tarihi belirtilmiş ilanlara uygulanır.</p><p class="field-error" id="date-error" role="alert"></p></details><input type="hidden" name="sort" value="${esc(sortKey(params))}">${params.has('favorites')?'<input type="hidden" name="favorites" value="1">':''}<div class="filter-apply"><p id="filter-result-count" role="status" aria-live="polite"></p><button type="submit" class="button full" id="filter-apply-button">Ürünleri göster ${icon('arrow')}</button></div></form>`}
function updateFilterPreview(){let form=$('.refined-filters');if(!form)return;let data=readFilterForm(form),params=new URLSearchParams(data),min=Number(data.min||0),max=data.max?Number(data.max):Infinity,numberBad=form.elements.min.validity.badInput||form.elements.max.validity.badInput,negative=min<0||max<0,priceBad=min>max||numberBad||negative,dateBad=data.dateStart&&data.dateEnd&&data.dateStart>data.dateEnd;$('#price-error').textContent=negative?'Fiyat 0’dan küçük olamaz.':numberBad?'Geçerli bir fiyat yaz.':min>max?'En az fiyat, en fazla fiyattan büyük olamaz.':'';$('#date-error').textContent=dateBad?'Başlangıç tarihi, bitiş tarihinden sonra olamaz.':'';const count=filterProducts(params).length;$('#filter-result-count').textContent=priceBad||dateBad?'Aralığı düzelterek devam edebilirsin.':count?count+' ürün bulundu.':'Bu seçimle ürün yok. Bir koşulu kaldırmayı dene.';let button=$('#filter-apply-button');button.disabled=!!(priceBad||dateBad);button.innerHTML=count+' ürünü göster '+icon('arrow');let selectedBrands=values(params,'brand');$('#brand-selection-summary').textContent=selectedBrands.length?selectedBrands.length+' marka seçili':'Birden fazla seçebilirsin';let withoutBrand=new URLSearchParams(params);withoutBrand.delete('brand');let eligible=filterProducts(withoutBrand);$$('[data-brand-count]',form).forEach(el=>{let b=el.dataset.brandCount,c=eligible.filter(p=>normalize(p.brand)===normalize(b)).length;el.textContent='('+c+')';let input=el.parentElement.querySelector('input');input.disabled=c===0&&!input.checked;el.parentElement.classList.toggle('unavailable',c===0&&!input.checked)});$$('[data-price-min]',form).forEach(b=>{let active=b.dataset.priceMin===(data.min||'')&&b.dataset.priceMax===(data.max||'');b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)})}
function filtersPage(params){return pageShell('Filtrele',`<a class="text-link" href="${route('catalog',Object.fromEntries(params))}">${icon('back')}Ürünlere geri dön</a><section class="filter-page">${filterForm(params)}</section>`)}
function catalog(params){let q=params.get('q')||'',discipline=params.get('discipline')||'',cat=params.get('category')||'',kind=params.get('kind')||'',mode=params.get('mode')||'',sort=sortKey(params),fav=params.has('favorites');let all=sortProducts(filterProducts(params),sort),total=all.length,pages=Math.max(1,Math.ceil(total/12)),page=Math.min(pages,Math.max(1,parseInt(params.get('page'),10)||1)),list=all.slice((page-1)*12,page*12);let title=fav?'Favorilerim':q?'“'+q+'” için ürünler':mode==='contact'?'Satıcıyla görüşülen ilanlar':mode==='online'&&kind==='listing'?'Online satın alınabilen ilanlar':discipline?discipline+(cat?' · '+(equipment.find(x=>x[0]===cat)?.[1]||cat):' ürünleri'):cat||(kind==='listing'?'Bireysel ilanlar':kind==='store'?'Mağaza ürünleri':params.has('deal')?'İndirimli ürünler':'Tüm ürünler');let chips=[];for(let b of values(params,'brand'))chips.push({key:'brand',value:b,label:b});for(let [key,label] of [['stock','Sadece stoktakiler'],['deal','İndirimli ürünler'],['condition',({new:'Sıfır',used:'İkinci el',refurbished:'Yenilenmiş',unknown:'Durumu belirtilmemiş'})[params.get('condition')]],['min','En az '+money(Number(params.get('min')||0))],['max','En fazla '+money(Number(params.get('max')||0))],['dateStart','Başlangıç: '+(params.get('dateStart')||'')],['dateEnd','Bitiş: '+(params.get('dateEnd')||'')]])if(params.get(key))chips.push({key,label});let reset=route('catalog',{q,favorites:fav?'1':''}),back=discipline?route('discipline',{name:discipline}):kind==='listing'?'#listings':'#techniques';let sortOptions=[['recommended','Önerilen sıralama'],['bestselling','En çok satanlar'],['most-viewed','En çok görüntülenenler'],['newest','Yeni gelenler'],['price-asc','En düşük fiyat'],['price-desc','En yüksek fiyat'],['discount-desc','En yüksek indirim'],['name','Ürün adı: A–Z']];const activeCount=['discipline','category','kind','mode','min','max','stock','deal','condition','dateStart','dateEnd'].filter(k=>params.get(k)).length+values(params,'brand').length;return `<div class="wrap page simple-catalog">${breadcrumb(title)}${heading(title)}<a class="text-link catalogue-back" href="${back}">${icon('back')}Seçimimi değiştir</a><div class="catalog-toolbar"><span class="results-count"><strong>${total} ürün</strong></span><button class="filter-open" data-action="filters">${icon('sliders')}Filtrele${activeCount?` <span class="filter-count">${activeCount}</span>`:''}</button><label class="sort-control"><span>Sırala</span><select id="sort">${sortOptions.map(([v,t])=>`<option value="${v}" ${sort===v?'selected':''}>${t}</option>`).join('')}</select></label></div>${chips.length?`<div class="active-filters">${chips.map(c=>`<button class="chip" data-remove-filter="${c.key}" ${c.value?`data-filter-value="${esc(c.value)}"`:''} aria-label="${esc(c.label)} filtresini kaldır">${esc(c.label)} ${icon('close')}</button>`).join('')}<a class="text-link filter-clear" href="${reset}">Tüm filtreleri temizle</a></div>`:''}<div class="product-grid">${list.length?list.map(productCard).join(''):empty(fav?'Henüz favorin yok.':'Bu seçimle ürün bulunamadı.',fav?'Ürün detayındaki Kaydet ve karşılaştır alanından favorilerine ekleyebilirsin.':'Filtreleri azaltmayı veya farklı bir kelime aramayı dene.',fav?'Ürünlere bak':activeCount?'Filtreleri temizle':'Tüm ürünlere bak',fav?'#catalog':activeCount?reset:'#catalog')}</div>${total>12?`<nav class="pagination" aria-label="Ürün sayfaları">${page>1?`<a class="button outline small" href="${route('catalog',{...Object.fromEntries(params),page:page-1})}">← Önceki</a>`:'<span></span>'}<span>${page} / ${pages}</span>${page<pages?`<a class="button small" href="${route('catalog',{...Object.fromEntries(params),page:page+1})}">Sonraki →</a>`:'<span></span>'}</nav>`:''}</div>`}

function sortKey(params){let v=params.get('sort');return ['recommended','bestselling','most-viewed','newest','price-asc','price-desc','discount-desc','name'].includes(v)?v:'recommended'}
